scripts:
Chart.defaults.font.family = "'Pretendard','Malgun Gothic',sans-serif";
Chart.defaults.color = '#5b6472';

new Chart(document.getElementById('barChart'), {
  type: 'bar',
  data: {
    labels: ['시장 요구치\n(WACC 9%)', '5년 FCF\n실제 CAGR', '5년 매출\n실제 CAGR', '애널리스트 컨센서스\n(FY27 EPS성장)'],
    datasets: [{
      data: [20.1, 1.9, 14.6, 14.0],
      backgroundColor: ['#c22','#1a56db','#5b8def','#0a7d3c'],
      borderRadius: 6
    }]
  },
  options: {
    plugins:{legend:{display:false}, title:{display:true, text:'연평균 성장률 비교 (%)', font:{size:12}}},
    scales:{y:{beginAtZero:true, ticks:{callback:v=>v+'%'}}}
  }
});
